if(!supportedLocales.includes(currentLocale))currentLocale='es';
const t=key=>window.FAMILY_I18N?.ui?.[currentLocale]?.[key]||window.FAMILY_I18N?.ui?.es?.[key]||key;
function setLocale(locale){currentLocale=supportedLocales.includes(locale)?locale:'es';localStorage.setItem('fej-cloud-locale',currentLocale);document.documentElement.lang=currentLocale;localizeGames()}
