let state, stats={}, view='home', selectedGame='trivia', difficulty='aleatorio', duration=45, rounds=1, modal=null, beginSent=false, timeUpSent=false, lastWinnerCelebration=null, lastStateJson='', whoAmIResumeBlockUntil=0, lastMysteryIndex=-1;
let playerId = roomCode?localStorage.getItem(playerStorageKey()):null, joinUrl='';

let deferredInstallPrompt=null;
const pwa={
  installed:window.matchMedia('(display-mode: standalone)').matches||window.navigator.standalone===true,
  helpOpen:false,
  isIOS:/iphone|ipad|ipod/i.test(navigator.userAgent),
  async install(){
    if(this.installed)return toast('La app ya está instalada');
    if(deferredInstallPrompt){
      deferredInstallPrompt.prompt();
      const choice=await deferredInstallPrompt.userChoice;
      if(choice.outcome==='accepted'){deferredInstallPrompt=null;this.installed=true;toast('¡App instalada!')}
      render();return;
    }
    this.helpOpen=true;renderInstallHelp();
  }
};
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredInstallPrompt=event;if(isMobile)enhanceMobileControls()});
window.addEventListener('appinstalled',()=>{pwa.installed=true;deferredInstallPrompt=null;document.querySelector('[data-install-app]')?.remove();toast('¡Familia en Juego quedó instalada!')});

const screenAwake={
  enabled:localStorage.getItem('fej-screen-awake')!=='off',sentinel:null,requesting:false,
  async request(){
    if((!isMobile&&!isTV)||!this.enabled||document.hidden||this.sentinel||this.requesting)return;
    this.requesting=true;
    try{
      if(!('wakeLock'in navigator))throw new Error('wake-lock-unavailable');
      this.sentinel=await navigator.wakeLock.request('screen');
      this.sentinel.addEventListener('release',()=>{this.sentinel=null;updateAwakeButton()},{once:true});
    }catch(_error){this.sentinel=null}
    finally{this.requesting=false;updateAwakeButton()}
  },
  async release(){if(this.sentinel){try{await this.sentinel.release()}catch(_error){}this.sentinel=null}updateAwakeButton()},
  toggle(){this.enabled=!this.enabled;localStorage.setItem('fej-screen-awake',this.enabled?'on':'off');this.enabled?this.request():this.release();updateAwakeButton()}
};
function updateAwakeButton(){const b=document.querySelector('[data-screen-awake]');if(!b)return;b.classList.toggle('active',screenAwake.enabled);b.textContent=screenAwake.enabled?'☀️ Pantalla activa':'🌙 Activar pantalla'}
function renderInstallHelp(){
  document.querySelector('.pwa-help-back')?.remove();if(!pwa.helpOpen)return;
  const ios=pwa.isIOS;
  const layer=document.createElement('div');layer.className='pwa-help-back';layer.innerHTML=`<div class="pwa-help" role="dialog" aria-modal="true"><button class="pwa-help-close" data-close-install aria-label="Cerrar">×</button><div class="pwa-help-icon">📲</div><h2>Instalar Familia en Juego</h2>${ios?`<p>En Safari, tocá <b>Compartir</b> <span class="share-symbol">▢↑</span> y después <b>Agregar a pantalla de inicio</b>.</p><ol><li>Abrí esta sala en Safari.</li><li>Tocá el botón Compartir.</li><li>Elegí “Agregar a pantalla de inicio”.</li></ol>`:`<p>En Chrome, tocá el menú <b>⋮</b> y elegí <b>Instalar aplicación</b> o <b>Agregar a pantalla principal</b>.</p><p class="pwa-help-note">Si aparece el botón automático de instalación, volvé a tocar “Instalar app”.</p>`}<button class="btn primary" data-close-install>Entendido</button></div>`;document.body.append(layer);layer.querySelectorAll('[data-close-install]').forEach(b=>b.onclick=()=>{pwa.helpOpen=false;layer.remove()})
}
function enhanceMobileControls(){
  if(!isMobile||!document.querySelector('.mobile')||document.querySelector('.mobile-utilities'))return;
  const controls=document.createElement('div');controls.className='mobile-utilities';controls.innerHTML=`${pwa.installed?'':`<button data-install-app>📲 Instalar app</button>`}<button data-screen-awake></button>`;document.querySelector('.mobile').prepend(controls);
  controls.querySelector('[data-install-app]')?.addEventListener('click',()=>pwa.install());
  controls.querySelector('[data-screen-awake]')?.addEventListener('click',()=>screenAwake.toggle());updateAwakeButton();
}

const games = {
  trivia:{icon:'🧠',name:'Carrera de Mente',desc:'Dos dados, 100 casillas y seis estrellas para conquistar.',instructions:'Cada equipo tira dos dados y avanza por un tablero de 100 casillas. La pregunta aparece tanto en el celular del participante como en la pantalla principal. Al elegir una opción, el sistema indica inmediatamente si es correcta, sin confirmación del anfitrión. El color de la casilla determina la categoría y cada acierto entrega una estrella de ese color. Para ganar hay que llegar a la meta y reunir al menos una estrella de cada categoría. Si un equipo llega con estrellas pendientes, permanece en la meta y responde únicamente preguntas de las categorías que le faltan. Hay casillas de avance, retroceso y comodines. Si dos equipos coinciden, eligen representantes y disputan un duelo por la estrella.'},
  mimica:{icon:'🎭',name:'Dígalo con Mímica',desc:'250 consignas cortas y un turno para cada participante.',instructions:'En cada ronda, los participantes actúan una vez cada uno, alternando los equipos y respetando su orden de registro. Antes de comenzar se eligen el tiempo por turno y la cantidad de rondas. Cada persona recibe en su celular una consigna secreta de hasta tres palabras y tiene cinco segundos para pensar. Luego actúa sin hablar ni hacer sonidos. Puede pasar hasta tres consignas y pedir hasta tres pistas por turno. Cuando pide una pista, aparece en la pantalla principal para que todos puedan verla.'},
  dibujo:{icon:'✏️',name:'Dibujo Relámpago',desc:'Cinco segundos para pensar y un dibujo secreto.',instructions:'Una persona recibe en su celular lo que debe dibujar y tiene cinco segundos para pensarlo sin mostrar la pantalla. Después comienza el reloj general. No puede usar letras, números ni gestos, y en este juego no se puede pasar.'},
  rapido:{icon:'🎪',name:'Reto Show Familiar',desc:'Actuación, música, destreza y muchas carcajadas.',instructions:'Cada turno propone un reto de actuación, imitación, canto, humor, coordinación, creatividad o destreza física segura para realizar en un salón. Antes de empezar se eligen el nivel y el tiempo disponible. Según la consigna puede participar una persona o colaborar todo el equipo. Se pueden usar objetos cotidianos sin correr riesgos. El anfitrión decide si el desafío fue superado.'},
  quien_dijo:{icon:'🤭',name:'¿Quién dijo qué?',desc:'Elegí una confesión y descubrí quién eligió cada frase.',instructions:'En cada ronda, cada participante recibe dos frases cómicas al azar en su celular y dispone del tiempo configurado para elegir la que más lo representa. Después aparecen juntas todas las frases elegidas, tanto en la pantalla principal como en cada celular. Cada jugador relaciona las frases con sus posibles autores, sin votar la propia. Cada coincidencia suma un punto para el equipo y, al terminar todas las rondas, gana el equipo que mejor conoce a la familia.'},
  quien_soy:{icon:'🎭',name:'¿Quién soy?',desc:'Celulares a la frente y preguntas para descubrir el personaje.',instructions:'Se juega un participante por vez durante la cantidad de rondas elegida. Al comenzar cada turno, el participante gira el teléfono y lo coloca horizontalmente sobre su frente. El personaje permanece oculto durante 10 segundos y luego ocupa toda la pantalla para que lo vean los demás. Si el celular se reactiva después de quedar inactivo, el personaje vuelve a ocultarse durante 5 segundos. Cada participante dispone de 120 segundos para hacer preguntas que se respondan con sí o no, por ejemplo: “¿Soy una persona real?”, “¿Aparezco en una película?”, “¿Tengo poderes?” o “¿Soy deportista?”. No se puede pedir el nombre, letras ni iniciales. Al terminar las rondas gana el equipo con más aciertos; si nadie adivinó, no hay ganador ni premio.'},
  tres_verdades:{icon:'🧐',name:'Tres verdades y una mentira',desc:'Cuatro datos plausibles y 90 segundos para detectar el falso.',instructions:'La pantalla principal presenta una figura histórica, deportista, artista, científica, superhéroe o personaje de Disney/Pixar junto con cuatro afirmaciones: tres son verdaderas y una es una mentira cuidadosamente disimulada. El sistema elige de forma rotativa un representante conectado por equipo. Solamente esos representantes ven las cuatro opciones en sus celulares y disponen de 90 segundos para marcar la mentira. Una vez elegida, la respuesta queda bloqueada. Si un solo equipo acierta, gana 3 puntos; si varios aciertan, empatan y reciben 1 punto cada uno; los equipos que fallan o no responden reciben 0.'},
  just_sing:{icon:'🎤',name:'Just Sing',desc:'Título, intérprete, época y un gran final cantando.',instructions:'En la pantalla principal aparece un fragmento breve y reconocible de una canción, normalmente de su estribillo. Todos los celulares participan en tres etapas: primero deben reconocer el título, después el intérprete y finalmente la época. En cada etapa aparecen cuatro opciones y gana el primer participante que elige la correcta. El equipo con más aciertos pasa al desafío final y debe cantar la canción. Si puede cantarla, suma 3 puntos; si no puede, conserva 1 punto.'}
  ,incognito:{icon:'🕵️',name:'Personaje Incógnito',desc:'Veinte pistas, un pulsador rojo y una identidad por descubrir.',instructions:'En cada ronda aparece un personaje oculto en la pantalla principal. Cada seis segundos se revela una pista nueva, comenzando por datos generales y terminando con pistas muy precisas. Cada participante tiene un gran pulsador rojo en su celular. Al pulsarlo, debe escribir quién cree que es; si falla, queda fuera de esa ronda y los demás continúan. Hay un máximo de veinte pistas. Acertar en las primeras 6 vale 3 puntos, entre la 7 y la 13 vale 2, y desde la 14 vale 1 punto. Si nadie acierta, se revela el personaje sin otorgar puntos.'}
  ,bomba:{icon:'💣',name:'Alerta Bomba',desc:'Acertijos, pases estratégicos y quince segundos para decidir.',instructions:'La alerta alterna jugadores entre equipos durante tres rondas. El portador tiene 15 segundos para arriesgar, pedir una pista o usar un poder. Arriesgar congela el reloj: si acierta, su equipo gana la ronda; si falla, queda eliminado hasta la ronda siguiente. Si todos los integrantes de un equipo fallan o el reloj llega a cero en sus manos, gana el rival. Pedir pista puede usarse siempre y pasa la alerta al siguiente jugador. Pasar, devolver y pausar cinco segundos pueden usarse una sola vez por participante durante toda la partida.'}
};
