  'Entretenimiento y Música':{color:'#f45b9b',icon:'🎵'},'Historia':{color:'#ef8a35',icon:'🏺'},'Geografía':{color:'#25a7df',icon:'🌎'},
  'Literatura':{color:'#9558d6',icon:'📚'},'Deportes':{color:'#20b982',icon:'🏅'},'Conocimientos generales':{color:'#f3c534',icon:'💡'}
