const music={ctx:null,track:null,enabled:localStorage.getItem('fej-music')!=='off',start(){if(!this.enabled)return;this.ctx||=new (window.AudioContext||window.webkitAudioContext)();this.ctx.resume();if(!this.track){this.track=new Audio('/audio/theme.mp3');this.track.loop=true;this.track.volume=.28}this.track.play().catch(()=>{})},stop(){this.track?.pause()},toggle(){this.enabled=!this.enabled;localStorage.setItem('fej-music',this.enabled?'on':'off');this.enabled?this.start():this.stop();render()},duck(on){if(this.track)this.track.volume=on ? .07 : .28},effect(ok=true){if(!this.ctx)return;[0,1,2].forEach((n)=>setTimeout(()=>{const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.frequency.value=(ok?[523,659,784]:[330,277,220])[n];g.gain.value=.035;o.connect(g).connect(this.ctx.destination);o.start();g.gain.exponentialRampToValueAtTime(.0001,this.ctx.currentTime+.22);o.stop(this.ctx.currentTime+.23)},n*100))}};
let instructionAudio=null,narratingGame=null;
function updateNarrationButton(){const button=$('[data-narrate]');if(button)button.textContent=narratingGame===selectedGame?'⏹ Detener explicación':'🔊 Escuchar explicación'}
function stopNarration(){if(instructionAudio){instructionAudio.pause();try{instructionAudio.currentTime=0}catch(_error){}instructionAudio=null}if('speechSynthesis'in window)speechSynthesis.cancel();narratingGame=null;music.duck(false);updateNarrationButton()}
const autoNarration={enabled:localStorage.getItem('fej-auto-narration')!=='off',toggle(){this.enabled=!this.enabled;localStorage.setItem('fej-auto-narration',this.enabled?'on':'off');if(!this.enabled)stopNarration();render()}};
function fallbackNarrate(gameId){if(!('speechSynthesis'in window)){stopNarration();return toast('La narración no está disponible')}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(games[gameId].instructions);u.lang=currentLocale==='pt-BR'?'pt-BR':currentLocale==='en'?'en-US':'es-AR';u.rate=.94;u.onend=()=>stopNarration();u.onerror=()=>stopNarration();speechSynthesis.speak(u);updateNarrationButton()}
function narrateGame(gameId){stopNarration();narratingGame=gameId;if(currentLocale!=='es')return fallbackNarrate(gameId);instructionAudio=new Audio(`/audio/instructions/${gameId}.m4a`);music.duck(true);instructionAudio.onended=()=>stopNarration();instructionAudio.onerror=()=>{instructionAudio=null;fallbackNarrate(gameId)};instructionAudio.play().then(updateNarrationButton).catch(()=>{instructionAudio=null;fallbackNarrate(gameId)});updateNarrationButton()}
function toggleNarration(gameId){if(narratingGame===gameId)stopNarration();else narrateGame(gameId)}
const reactionPhrases={
  good:[['¡RESPUESTA ESTELAR!','¡La rompieron!'],['¡QUÉ EQUIPAZO!','Esa respuesta vino con brillo propio'],['¡SÍÍÍÍ!','¡Directo a la colección de estrellas!'],['¡GENIALES!','La familia está encendida'],['¡PUNTO Y FESTEJO!','¡Eso merece una vuelta olímpica!']],
  bad:[['¡UUUH, CASI!','La respuesta correcta pasó saludando'],['¡BUUUU… CON CARIÑO!','El cerebro pidió cinco minutos de recreo'],['¡NO ERA ESA!','Esa respuesta se fue de paseo'],['¡AY, AY, AY!','La próxima viene con revancha'],['¡PLOP!','Hasta el dado se quedó pensando']]
};
function showReaction(ok,custom){document.querySelector('.reaction-overlay')?.remove();const [title,subtitle]=custom?[custom,'']:reactionPhrases[ok?'good':'bad'][Math.floor(Math.random()*reactionPhrases[ok?'good':'bad'].length)],layer=document.createElement('div');layer.className=`reaction-overlay ${ok?'good':'bad'}`;layer.innerHTML=`<div class="reaction-card"><div class="reaction-face">${ok?'🤩':'😜'}</div><strong>${title}</strong><p>${subtitle}</p></div>`;const emojis=ok?['⭐','🎉','✨','🥳','🏆']:['🙈','🥴','😅','🍅','💨'];for(let i=0;i<30;i++){const e=document.createElement('i');e.textContent=emojis[i%emojis.length];e.style.setProperty('--x',Math.random()*100+'vw');e.style.setProperty('--delay',Math.random()*.55+'s');e.style.setProperty('--spin',(Math.random()*720-360)+'deg');layer.append(e)}document.body.append(layer);if(ok)confetti();setTimeout(()=>{layer.classList.add('leaving');setTimeout(()=>layer.remove(),450)},2200)}
document.addEventListener('pointerdown',()=>{music.start();screenAwake.request()},{once:true});
document.addEventListener('visibilitychange',()=>{if(!document.hidden){screenAwake.request();if(isMobile&&state?.game?.id==='quien_soy'){whoAmIResumeBlockUntil=Date.now()+5000;render();setTimeout(()=>{if(state?.game?.id==='quien_soy')render()},5100)}}});
window.addEventListener('pagehide',()=>screenAwake.release());

const post = async body => {
  const headers={'Content-Type':'application/json'},hostToken=localStorage.getItem(hostTokenKey()),playerToken=localStorage.getItem(playerTokenKey());
  if(hostToken)headers['X-Host-Token']=hostToken;if(playerToken)headers['X-Player-Token']=playerToken;
  const res = await fetch('/api/action',{method:'POST',headers,body:JSON.stringify({room:roomCode,action:body})});
  const data = await res.json();
  if(!res.ok||!data.ok)throw new Error(data.error||'No se pudo completar la acción');
  state=data.state;lastStateJson=JSON.stringify(state);render();return data;
};
const esc = s => String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const team = id => state.teams.find(t=>t.id===id);
const player = id => state.players.find(p=>p.id===id);
const toast = msg => {const el=$('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2200)};
function renderWhoSaidMobile(){
  const me=player(playerId);if(!me)return renderJoin();const t=team(me.teamId),choices=state.whoSaidChoices?.[me.id]||[],selected=state.whoSaidSelected?.[me.id],order=state.whoSaidOrder||[],myGuesses=state.whoSaidGuesses?.[me.id]||{};let content='';
  if(state.status==='who_said_choose')content=selected?`<div class="waiting">✅🤫</div><h2>¡Frase elegida!</h2><p>El reloj seguirá hasta completar los 60 segundos.</p>`:`<span class="eyebrow">TENÉS 60 SEGUNDOS</span><h2>¿Cuál te representa mejor?</h2><div class="team-choice">${choices.map((phrase,index)=>`<button data-who-said-choice="${index}">${esc(phrase)}</button>`).join('')}</div>`;
  else if(state.status==='who_said_guess'){const usedNumbers=new Set(Object.keys(myGuesses));content=`<span class="eyebrow">MIRÁ LAS FRASES NUMERADAS EN LA TV</span><h2>¿Quién dijo qué?</h2><p>Elegí junto a cada persona el número de la frase que creés que eligió.</p><div class="who-said-number-grid">${(state.whoSaidPlayers||[]).map(id=>{const selectedIndex=Object.keys(myGuesses).find(index=>myGuesses[index]===id);return `<div class="who-said-person"><strong>${esc(player(id)?.name)}</strong><div>${order.map(item=>{const key=String(item.roundIndex),chosen=selectedIndex===key,used=usedNumbers.has(key)&&!chosen;return `<button data-who-said-number="${item.roundIndex}" data-who-said-person="${id}" class="${chosen?'chosen':''}" ${used?'disabled':''}>${item.roundIndex+1}</button>`}).join('')}</div></div>`}).join('')}</div><p><b>${Object.keys(myGuesses).length}</b> de ${order.length} personas asignadas.</p>`}
  else if(state.status==='who_said_reveal'){const correct=order.filter(item=>myGuesses[String(item.roundIndex)]===item.playerId).length;content=`<div class="waiting">🎉🤭</div><h2>¡Acertaste ${correct} de ${order.length}!</h2>${order.map(item=>`<div class="statline"><span><b>#${item.roundIndex+1}</b> “${esc(item.prompt)}”</span><b>${esc(player(item.playerId)?.name)}</b></div>`).join('')}`}
  else if(state.status==='game_complete'){const points=state.whoSaidTeamPoints||{};content=`<div class="waiting">${state.winnerTeam?'🏆🤭':'🤝🤭'}</div><h2>${state.winnerTeam?`¡Ganó ${esc(state.winnerTeam.name)}!`:'¡Empate!'}</h2><p>Tu equipo consiguió <b>${points[t?.id]||0}</b> aciertos.</p>`}
  else content=`<div class="waiting">⏳</div><h2>Preparando el juego…</h2>`;
  app.innerHTML=`<main class="mobile"><div class="brand"><div class="logo">🤭</div><div><h1>¿Quién dijo qué?</h1><small>Sala ${state.room}</small></div></div><section class="mobile-card"><div class="player" style="margin-bottom:18px;text-align:left"><div class="avatar">${esc(me.name.slice(0,2).toUpperCase())}</div><div><b>${esc(me.name)}</b><br><small>${esc(t?.name)}</small></div><span class="online" style="margin-left:auto"></span></div>${content}</section></main>`;bind();
}
function renderWhoAmIMobile(){
  const me=player(playerId);if(!me)return renderJoin();const t=team(me.teamId),card=state.whoAmIAssignments?.[me.id]||{},guessed=(state.whoAmIGuessed||[]).includes(me.id);let content='';
  if(card.prompt&&state.status==='playing'&&state.activePlayer===me.id&&Date.now()>=whoAmIResumeBlockUntil){app.innerHTML=`<main class="whoami-landscape ${guessed?'guessed':''}"><div class="whoami-rotate-hint">↻ Girá el celular</div><div class="whoami-screen"><span>${guessed?'✅ ADIVINÓ':esc(card.category||'¿QUIÉN SOY?')}</span><strong>${esc(card.prompt)}</strong><small>${guessed?esc(me.name):'PANTALLA HACIA LOS DEMÁS · NO MIRES'}</small></div></main>`;return bind()}
  if(state.status==='game_complete'){const points=state.whoAmIPoints||{},best=Math.max(0,...Object.values(points));content=`<div class="waiting">${state.winnerTeam?'🏆🎭':best?'🤝🎭':'🎭'}</div><h2>${state.winnerTeam?`¡Ganó ${esc(state.winnerTeam.name)}!`:best?'¡Empate!':'Esta vez no hubo ganador'}</h2><p>Tu equipo consiguió <b>${points[t?.id]||0}</b> aciertos.</p>`}
  else if(state.activePlayer===me.id&&(state.status==='countdown'||Date.now()<whoAmIResumeBlockUntil))content=`<span class="eyebrow">NO MIRES LA PANTALLA</span><div class="waiting">📱⬆️</div><h2>Giralo y ponelo en tu frente</h2><p>${state.status==='countdown'?'El personaje aparecerá automáticamente después de 10 segundos.':'Por seguridad, volverá a aparecer en 5 segundos.'}</p>`;
  else if(state.activePlayer!==me.id)content=`<div class="waiting">⏳</div><h2>Turno de ${esc(player(state.activePlayer)?.name||'otro participante')}</h2><p>Tu próximo personaje aparecerá cuando llegue tu turno.</p>`;
  else if(state.status==='result')content=`<div class="waiting">${guessed?'✅🎭':'⏰🎭'}</div><h2>${guessed?'¡Adivinaste!':'Terminó tu turno'}</h2><p>Entregale el turno al siguiente participante.</p>`;
  else content=`<span class="eyebrow">${guessed?'✅ ¡ADIVINASTE!':'PANTALLA HACIA LOS DEMÁS'}</span><div class="secret"><small>${esc(card.category)}</small><div class="question">${esc(card.prompt||'Preparando…')}</div></div><p>${guessed?'El anfitrión ya registró tu acierto.':`No mires el teléfono. Preguntá cosas que se respondan con “sí” o “no”.`}</p>`;
  app.innerHTML=`<main class="mobile"><div class="brand"><div class="logo">🎭</div><div><h1>¿Quién soy?</h1><small>Sala ${state.room}</small></div></div><section class="mobile-card"><div class="player" style="margin-bottom:18px;text-align:left"><div class="avatar">${esc(me.name.slice(0,2).toUpperCase())}</div><div><b>${esc(me.name)}</b><br><small>${esc(t?.name)}</small></div><span class="online" style="margin-left:auto"></span></div>${content}</section></main>`;bind();
}
function renderThreeTruthsMobile(){
  const me=player(playerId);if(!me)return renderJoin();const t=team(me.teamId),prompt=state.prompt||{},representative=state.truthRepresentatives?.[t?.id]===me.id,answer=state.truthAnswers?.[t?.id],answered=answer!==undefined,outcome=state.truthOutcome||{},correct=prompt.correct;let content='';
  if(state.status==='playing'&&representative&&!answered)content=`<span class="eyebrow">REPRESENTÁS A ${esc(t?.name)}</span><h2>¿Cuál es la mentira?</h2><p><b>${esc(prompt.prompt)}</b></p><div class="team-choice">${(prompt.statements||[]).map((item,index)=>`<button data-answer-lie="${index}">${esc(item.text)}</button>`).join('')}</div><p>Elegí con cuidado: no se puede cambiar.</p>`;
  else if(state.status==='playing'&&representative)content=`<div class="waiting">🔒</div><h2>Respuesta bloqueada</h2><p>Elegiste: <b>${esc(prompt.statements?.[answer]?.text)}</b></p><p>Esperá a los demás equipos.</p>`;
  else if(state.status==='playing')content=`<div class="waiting">🧐</div><h2>Representa a tu equipo ${esc(player(state.truthRepresentatives?.[t?.id])?.name||'otro participante')}</h2><p>Ayudalo a pensar, pero la respuesta se confirma desde su celular.</p>`;
  else if(state.status==='result'){const earned=outcome.points?.[t?.id]||0;content=`<div class="waiting">${earned===3?'🏆':earned===1?'🤝':'😜'}</div><h2>${earned===3?'¡Ganaron la ronda!':earned===1?'¡Empataron!':'Esta vez no sumaron'}</h2><p>La mentira era: <b>${esc(prompt.statements?.[correct]?.text)}</b></p><p>El equipo suma <b>${earned} punto${earned===1?'':'s'}</b>.</p>`}
  else content=`<div class="waiting">⏳</div><h2>Preparando la próxima figura…</h2>`;
  app.innerHTML=`<main class="mobile"><div class="brand"><div class="logo">🧐</div><div><h1>Tres verdades y una mentira</h1><small>Sala ${state.room}</small></div></div><section class="mobile-card"><div class="player" style="margin-bottom:18px;text-align:left"><div class="avatar">${esc(me.name.slice(0,2).toUpperCase())}</div><div><b>${esc(me.name)}</b><br><small>${esc(t?.name)}</small></div><span class="online" style="margin-left:auto"></span></div>${content}</section></main>`;bind();
}
function renderJustSingMobile(){
  const me=player(playerId);if(!me)return renderJoin();const t=team(me.teamId),phase=state.singPhase,answered=state.singAnswers?.[me.id]!==undefined,labels={title:'¿Cuál es el título?',artist:'¿Quién la interpreta?',era:'¿De qué época es?'};let content='';
  if(state.status==='sing_question'&&!answered)content=`<span class="eyebrow">${phase==='title'?'TÍTULO':phase==='artist'?'INTÉRPRETE':'ÉPOCA'}</span><h2>${labels[phase]}</h2><p>Mirá el fragmento de letra en la pantalla principal y elegí una opción.</p><div class="team-choice">${(state.singOptions||[]).map((option,index)=>`<button data-answer-song="${index}">${esc(option)}</button>`).join('')}</div>`;
  else if(state.status==='sing_question')content=`<div class="waiting">🔒🎵</div><h2>Respuesta enviada</h2><p>Esperá a que alguien encuentre la opción correcta.</p>`;
  else if(state.status==='sing_perform'){const finalist=team(state.singFinalistTeam);content=`<div class="waiting">🎤🎶</div><h2>${finalist?.id===t?.id?'¡Su equipo debe cantar!':`Canta ${esc(finalist?.name)}`}</h2><p><b>${esc(state.prompt?.title)}</b> · ${esc(state.prompt?.artist)}</p>`}
  else if(state.status==='game_complete'){content=`<div class="waiting">${state.winnerTeam?'🏆🎤':'🎵'}</div><h2>${state.winnerTeam?`¡Ganó ${esc(state.winnerTeam.name)}!`:'No hubo ganador'}</h2><p>${state.singAward?`Sumó ${state.singAward} punto${state.singAward===1?'':'s'}.`:'La trivia terminó sin aciertos.'}</p>`}
  else content=`<div class="waiting">📱🎤</div><h2>Esperando participantes</h2>`;
  app.innerHTML=`<main class="mobile"><div class="brand"><div class="logo">🎤</div><div><h1>Just Sing</h1><small>Sala ${state.room}</small></div></div><section class="mobile-card"><div class="player" style="margin-bottom:18px;text-align:left"><div class="avatar">${esc(me.name.slice(0,2).toUpperCase())}</div><div><b>${esc(me.name)}</b><br><small>${esc(t?.name)}</small></div><span class="online" style="margin-left:auto"></span></div>${content}</section></main>`;bind();
}

function renderIncognitoMobile(){const me=player(playerId);if(!me)return renderJoin();const t=team(me.teamId),locked=(state.mysteryLockedPlayers||[]).includes(me.id),buzzed=state.mysteryBuzzPlayer===me.id,winner=state.mysteryRoundWinner;let content='';
  if(state.status==='mystery_result'||state.status==='game_complete')content=`<div class="waiting">${winner?'🎉🕵️':'🔎'}</div><h2>${winner?`¡${esc(winner.player)} lo descubrió!`:'Se reveló el personaje'}</h2><div class="mystery-answer">${esc(state.prompt?.answer||'')}</div><p>${winner?`El equipo sumó ${winner.points} punto${winner.points===1?'':'s'}.`:'Esta ronda quedó sin puntos.'}</p>`;
  else if(buzzed&&state.status==='mystery_guess')content=`<span class="eyebrow">TU OPORTUNIDAD</span><h2>¿Quién es?</h2><form id="mystery-guess"><input class="input mystery-input" name="guess" required autofocus autocomplete="off" placeholder="Escribí el nombre"><button class="btn primary">Enviar respuesta</button></form><p>Una vez enviada no se puede cambiar.</p>`;
  else if(locked)content=`<div class="waiting">😅</div><h2>Esta vez no fue</h2><p>Ya usaste tu oportunidad en esta ronda. Seguí las pistas junto a tu equipo.</p>`;
  else content=`<span class="eyebrow">PISTA ${(state.mysteryClueIndex||0)+1} DE 20</span><h2>¿Ya sabés quién es?</h2><button class="mystery-buzzer" data-mystery-buzz>¡ARRIESGO!</button><p>Al pulsar deberás escribir el nombre. Sólo tenés una oportunidad por ronda.</p>`;
  app.innerHTML=`<main class="mobile"><div class="brand"><div class="logo">🕵️</div><div><h1>Personaje Incógnito</h1><small>${esc(t?.name)}</small></div></div><section class="mobile-card mystery-mobile">${content}</section></main>`;bind()}
function renderBombMobile(){const me=player(playerId);if(!me)return renderJoin();const t=team(me.teamId),holder=state.bombHolder===me.id,eliminated=(state.bombEliminated||[]).includes(me.id),guessing=state.bombGuessPlayer===me.id&&state.status==='bomb_guess',used=state.bombPowerUsed?.[me.id]||{};let content='';
  if(state.status==='bomb_result'||state.status==='game_complete')content=`<div class="waiting">💥🎉</div><h2>${state.bombRoundWinner?`¡Ganó ${esc(state.bombRoundWinner.name)}!`:state.winnerTeam?`¡Ganó ${esc(state.winnerTeam.name)}!`:'Fin de la partida'}</h2><p>La respuesta era <b>${esc(state.prompt?.answer||'')}</b>.</p>`;
  else if(guessing)content=`<span class="eyebrow">RELOJ CONGELADO</span><h2>Escribí tu respuesta</h2><form id="bomb-guess"><input class="input mystery-input" name="guess" required autofocus autocomplete="off"><button class="btn primary">Confirmar respuesta</button></form>`;
  else if(eliminated)content=`<div class="waiting">😅</div><h2>Quedaste fuera de esta ronda</h2><p>Tu equipo todavía puede salvarse.</p>`;
  else if(holder)content=`<span class="eyebrow">¡LA ALERTA ESTÁ EN TUS MANOS!</span><div class="bomb-mobile-clock"><span id="timer">15</span></div><button class="mystery-buzzer" data-bomb-move="risk">¡ARRIESGAR!</button><div class="bomb-actions"><button data-bomb-move="hint">💡 Pista</button><button data-bomb-move="pass" ${used.pass?'disabled':''}>⏭ Pasar</button><button data-bomb-move="return" ${used.return?'disabled':''}>↩ Devolver</button><button data-bomb-move="pause" ${used.pause?'disabled':''}>⏸ +5 segundos</button></div>`;
  else content=`<div class="waiting">💣</div><h2>La alerta está con ${esc(player(state.bombHolder)?.name||'otro jugador')}</h2><p>Preparáte: puede llegar a tu celular.</p>`;
  app.innerHTML=`<main class="mobile"><div class="brand"><div class="logo">💣</div><div><h1>Alerta Bomba</h1><small>${esc(t?.name)}</small></div></div><section class="mobile-card">${content}</section></main>`;bind()}
function makePlayerId(){
  try{
    if(globalThis.crypto?.randomUUID)return'p'+crypto.randomUUID().replace(/-/g,'').slice(0,12);
    if(globalThis.crypto?.getRandomValues){const bytes=new Uint8Array(6);crypto.getRandomValues(bytes);return'p'+[...bytes].map(n=>n.toString(16).padStart(2,'0')).join('')}
  }catch(_error){}
  return'p'+Date.now().toString(36)+Math.random().toString(36).slice(2,8);
}

async function init(){
  if(!roomCode)return isTV?renderTVEntry():renderCloudEntry();
  const data=await fetchCloudState();
  state=data.state;setLocale(state.locale||currentLocale);stats=data.contentStats;joinUrl=data.joinUrl;lastStateJson=JSON.stringify(state);lastMysteryIndex=state.mysteryClueIndex??-1;
  if(!isMobile&&state.game)view='play';
  setInterval(pollCloudState,900);
  render();setInterval(updateTimer,250);setInterval(updateBombTimer,250);
}

async function fetchCloudState(){
  const headers={},playerToken=localStorage.getItem(playerTokenKey()),hostToken=localStorage.getItem(hostTokenKey());if(playerToken)headers['X-Player-Token']=playerToken;if(hostToken)headers['X-Host-Token']=hostToken;
  const query=new URLSearchParams({room:roomCode});if(playerId)query.set('player',playerId);
  const res=await fetch(`/api/state?${query}`,{headers}),data=await res.json();if(!res.ok||!data.ok)throw new Error(data.error||'No se pudo abrir la sala');return data;
}
async function pollCloudState(){
  try{const data=await fetchCloudState(),json=JSON.stringify(data.state);if(json===lastStateJson)return;lastStateJson=json;if(data.state.mysteryClueIndex!==lastMysteryIndex){lastMysteryIndex=data.state.mysteryClueIndex;timeUpSent=false}state=data.state;setLocale(state.locale||currentLocale);stats=data.contentStats;joinUrl=data.joinUrl;render()}catch(_error){}
}
function renderCloudEntry(){
  app.innerHTML=`<main class="cloud-entry"><section class="cloud-welcome"><div class="cloud-logo">🎲</div><span class="eyebrow">${t('cloud')}</span><h1>${t('welcome')}</h1><p>${t('welcomeText')}</p><form id="create-cloud-room"><label>${t('language')}</label><select class="input cloud-language" name="locale"><option value="es" ${currentLocale==='es'?'selected':''}>🇦🇷 ${t('spanish')}</option><option value="pt-BR" ${currentLocale==='pt-BR'?'selected':''}>🇧🇷 ${t('portuguese')}</option><option value="en" ${currentLocale==='en'?'selected':''}>🇺🇸 ${t('english')}</option></select><button class="btn primary">${t('create')}</button></form><div class="cloud-divider"><span>${t('or')}</span></div><form id="enter-cloud-room"><label>${t('roomCode')}</label><div class="row"><input class="input" name="room" required maxlength="8" autocomplete="off" placeholder="ABCDE"><button class="btn secondary">${t('enter')}</button></div></form></section></main>`;
  $('.cloud-language').onchange=event=>{setLocale(event.target.value);renderCloudEntry()};
  $('#create-cloud-room').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button'),locale=new FormData(form).get('locale');button.disabled=true;button.textContent=t('creating');try{const res=await fetch('/api/rooms',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({locale})}),data=await res.json();if(!res.ok||!data.ok)throw new Error(data.error);roomCode=data.room;setLocale(locale);localStorage.setItem(hostTokenKey(),data.hostToken);location.href=`/?room=${encodeURIComponent(roomCode)}`}catch(error){button.disabled=false;button.textContent=t('create');toast(error.message||t('invalidRoom'))}};
  $('#enter-cloud-room').onsubmit=event=>{event.preventDefault();const code=String(new FormData(event.currentTarget).get('room')||'').trim().toUpperCase();location.href=`/?join=1&room=${encodeURIComponent(code)}`};
}
function renderTVEntry(){app.innerHTML=`<main class="cloud-entry tv-entry"><section class="cloud-welcome"><div class="cloud-logo">📺</div><span class="eyebrow">FAMILIA EN JUEGO · TV</span><h1>${t('tvTitle')}</h1><p>${t('tvText')}</p><form id="enter-tv-room"><label>${t('roomCode')}</label><input class="input" name="room" required maxlength="8" autocomplete="off" autofocus placeholder="ABCDE"><button class="btn primary">${t('connectTV')}</button></form></section></main>`;$('#enter-tv-room').onsubmit=event=>{event.preventDefault();const code=String(new FormData(event.currentTarget).get('room')||'').trim().toUpperCase();location.href=`/tv?room=${encodeURIComponent(code)}`}}

function render(){
  if(!state)return;
  if(isMobile)return state.game?.id==='bomba'?renderBombMobile():state.game?.id==='incognito'?renderIncognitoMobile():state.game?.id==='just_sing'?renderJustSingMobile():state.game?.id==='tres_verdades'?renderThreeTruthsMobile():state.game?.id==='quien_soy'?renderWhoAmIMobile():state.game?.id==='quien_dijo'?renderWhoSaidMobile():state.game?.id==='trivia'&&state.status==='result'?renderTriviaMobileResult():renderMobile();
  if(isTV)return renderTV();
  if(state.status!=='countdown')beginSent=false;if(!['playing','who_said_choose'].includes(state.status))timeUpSent=false;
  app.innerHTML=`<main class="shell">${topbar()}${statusStrip()}${view==='play'&&state.game?playView():view==='teams'?teamsView():view==='settings'?settingsView():homeView()}</main>${modalHtml()}`;
  const gameCountLabel=[...document.querySelectorAll('.eyebrow')].find(element=>element.textContent.includes('FORMAS DE REÍRSE'));if(gameCountLabel)gameCountLabel.textContent=`${Object.keys(games).length} FORMAS DE REÍRSE`;
  document.querySelectorAll('[data-game]').forEach(card=>{const icon=card.querySelector('.game-icon');if(icon){const cover=document.createElement('img');cover.className='game-cover';cover.src=`/images/games/${card.dataset.game}.webp`;cover.alt=`Imagen de ${games[card.dataset.game].name}`;icon.replaceWith(cover)}});
  bind();updateTimer();
  const celebrationId=state.winnerTeam?.celebrationId;
  if(celebrationId&&celebrationId!==lastWinnerCelebration){const winnerName=state.winnerTeam.name;lastWinnerCelebration=celebrationId;setTimeout(()=>{music.effect(true);showReaction(true,`🏆 ¡GANÓ ${winnerName}!`)},50)}
}

function renderTV(){const body=state.game?playView():`<section class="tv-waiting"><div>🎲📺</div><span class="eyebrow">PANTALLA CONECTADA</span><h1>Familia en Juego</h1><p>La partida aparecerá aquí cuando el anfitrión elija un juego.</p><strong>${t('room')} ${esc(state.room)} · ${state.locale||'es'}</strong></section>`;app.innerHTML=`<main class="tv-shell"><button class="tv-fullscreen" data-tv-fullscreen>⛶ Pantalla completa</button>${statusStrip()}${body}</main>`;$('[data-tv-fullscreen]').onclick=async()=>{try{await document.documentElement.requestFullscreen?.();await screenAwake.request()}catch(_error){}};updateTimer()}

function topbar(){return `<header class="topbar">
  <div class="brand"><div class="logo">🎲</div><div><h1>Familia en Juego</h1><small>Donde todos ganan recuerdos</small></div></div>
  <nav class="nav"><button data-view="home" class="${view==='home'?'active':''}">${t('home')}</button><button data-view="teams" class="${view==='teams'?'active':''}">${t('teams')}</button><button data-view="settings" class="${view==='settings'?'active':''}">${t('content')}</button></nav>
  <div class="row"><button class="music-btn tv-cast-btn" data-tv>📺 ${t('projectTV')}</button><button class="music-btn ${music.enabled?'on':''}" data-music>${music.enabled?'♫ Música':'♪ Sin música'}</button><button class="music-btn ${autoNarration.enabled?'on':''}" data-auto-narration>${autoNarration.enabled?'🔊 Lectura auto':'🔇 Lectura apagada'}</button><div class="room-chip">${t('room').toUpperCase()} <b>${state.room}</b> · ${state.locale||'es'}</div></div>
</header>`}

function statusStrip(){const active=team(state.activeTeam);return `<section class="status-strip"><div class="turn-pill"><span class="pulse"></span><small>TURNO</small><b>${state.game?esc(active?.name||'A definir'):'Esperando partida'}</b></div><div class="mini-scores">${state.teams.map(t=>`<span><i style="background:${t.color}"></i>${esc(t.name)} <b>${t.score}</b></span>`).join('')}</div>${state.game?`<div class="current-game">${games[state.game.id].icon} ${games[state.game.id].name} · ${state.game.duration}s · ${state.game.rounds||1} ronda${(state.game.rounds||1)===1?'':'s'}</div>`:'<div class="current-game">🎉 ¡Todo listo!</div>'}</section>`}

function starsHtml(t){return `<div class="star-row">${triviaCategories.map(c=>`<span class="star ${t.stars?.[c]?'earned':''}" style="--star:${categoryMeta[c].color}" title="${esc(c)}">★<b>${t.stars?.[c]||0}</b></span>`).join('')}</div>`}
function scorePanel(){const max=state.game?.id==='trivia'?100:12;return `<section class="panel"><div class="section-title"><h3>🏆 Marcador familiar</h3><button class="btn ghost" data-action="reset">Reiniciar</button></div><div class="score-list">${state.teams.map(t=>`<div class="team-score"><div class="team-head"><span><i class="team-dot" style="background:${t.color}"></i>${esc(t.name)} ${t.finished?'🏆':''}</span><span class="big-score">${t.score}</span></div><div class="track"><i style="width:${Math.min(100,t.position/max*100)}%;background:${t.color}"></i></div>${state.game?.id==='trivia'?starsHtml(t):''}</div>`).join('')}</div></section>`}

function homeView(){return `<div class="grid"><div><section class="panel hero"><span class="eyebrow">NOCHE DE JUEGOS</span><h2>¿Qué aventura jugamos hoy?</h2><p>Elegí un desafío, armá los equipos y convertí cada celular en una pieza del juego.</p><div class="hero-actions"><button class="btn primary" data-scroll="games">Elegir juego ↓</button><button class="btn ghost" data-view="teams">Preparar equipos</button></div></section>
  <section class="panel" id="games" style="margin-top:24px"><div class="section-title"><div><span class="eyebrow">9 FORMAS DE REÍRSE</span><h3 style="margin:3px 0">Elegí el próximo desafío</h3></div><span>${Object.values(stats).reduce((a,b)=>a+b,0)} consignas</span></div><div class="game-grid">${Object.entries(games).map(([id,g])=>`<article class="game-card ${selectedGame===id?'selected':''}" data-game="${id}"><span class="tag">${stats[id]||0} tarjetas</span><span class="game-icon">${g.icon}</span><h3>${g.name}</h3><p>${g.desc}</p><button class="btn primary play-game" data-play-game="${id}">Jugar →</button></article>`).join('')}</div></section></div>
  <aside>${scorePanel()}${joinPanel()}</aside></div>`}

function joinPanel(){const url=joinUrl||`${location.origin}/?join=1&room=${encodeURIComponent(roomCode)}`;const qr=`https://quickchart.io/qr?size=320&margin=1&text=${encodeURIComponent(url)}`;return `<section class="panel qr-wrap" style="margin-top:24px"><span class="eyebrow">CELULARES</span><h3>Escaneá y unite</h3><img class="qr" src="${qr}" alt="Código QR para unirse"><div class="join-url">${esc(url)}</div><button class="btn secondary qr-expand-btn" data-open-qr>⛶ Ampliar QR</button><p style="font-size:13px;color:var(--muted);margin:10px 0 0">Desde cualquier conexión · Código <b>${state.room}</b></p></section>`}

function teamsView(){return `<div class="grid"><section class="panel"><div class="section-title"><div><span class="eyebrow">JUGADORES Y EQUIPOS</span><h2 style="font-size:32px;margin:3px 0">Armemos los equipos</h2></div><button class="btn secondary" data-add-team>+ Nuevo equipo</button></div><div class="team-admin-grid">${state.teams.map(t=>`<div class="team-admin" style="--team:${t.color}"><span class="team-badge">${t.id==='sol'?'☀️':t.id==='luna'?'🚀':'⭐'}</span><div><b>${esc(t.name)}</b><small>${state.players.filter(p=>p.teamId===t.id).length} integrantes</small></div><div class="team-actions"><button class="icon-btn edit" data-edit-team="${t.id}" title="Editar ${esc(t.name)}" aria-label="Editar ${esc(t.name)}">✎</button><button class="icon-btn danger" data-delete-team="${t.id}" title="Borrar ${esc(t.name)}" aria-label="Borrar ${esc(t.name)}" ${state.teams.length<=1?'disabled':''}>×</button></div></div>`).join('')}</div><form id="add-player" class="row add-person"><input class="input" name="name" required placeholder="Nombre del participante" style="flex:1"><select class="input" name="teamId">${state.teams.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select><button class="btn primary">+ Participante</button></form><div class="players" style="margin-top:20px">${state.players.length?state.players.map(p=>`<div class="player"><div class="avatar">${esc(p.name.slice(0,2).toUpperCase())}</div><div class="player-info"><b>${esc(p.name)}</b><br><small>${p.online?'📱 Conectado':'Agregado por anfitrión'} · ${esc(team(p.teamId)?.name)}</small></div><button class="btn player-edit-btn" data-edit-player="${p.id}" aria-label="Editar participante ${esc(p.name)}">✏️ Cambiar equipo</button><button class="icon-btn danger" data-delete-player="${p.id}" title="Borrar ${esc(p.name)}" aria-label="Borrar participante ${esc(p.name)}">×</button></div>`).join(''):`<div class="empty">Todavía no hay participantes. Agregalos o pediles que escaneen el QR.</div>`}</div></section><aside>${joinPanel()}${scorePanel()}</aside></div>`}

function settingsView(){return `<div class="grid"><section class="panel"><span class="eyebrow">BANCO DE CONTENIDO</span><h2 style="font-size:32px">Preguntas que siempre crecen</h2><p style="color:var(--muted)">La app ya trae contenido en español, separado por juego y dificultad. Podés sumar nuevos paquetes desde una URL pública en formato JSON.</p>${Object.entries(games).map(([id,g])=>`<div class="statline"><span>${g.icon} ${g.name}</span><b>${stats[id]||0} consignas</b></div>`).join('')}<form id="import-content" class="field" style="margin-top:24px"><label>URL de un paquete de contenido</label><div class="row"><input class="input" name="url" type="url" placeholder="https://ejemplo.com/preguntas.json" style="flex:1" required><button class="btn primary">Importar</button></div></form><p style="font-size:12px;color:var(--muted)">La fuente debe permitir acceso público y respetar la estructura explicada en README.md.</p></section><aside><section class="panel"><h3>💡 Receta para una gran noche</h3><p>Mezclá edades en cada equipo, alterná quién pasa al frente y usá “Mezclado” para que nadie sepa qué viene.</p><p>Los puntos valen <b>100 / 200 / 300</b> según la dificultad.</p></section></aside></div>`}

function board(){return `<div class="category-legend">${triviaCategories.map(c=>`<span><i style="background:${categoryMeta[c].color}"></i>${categoryMeta[c].icon} ${esc(c)}</span>`).join('')}</div><div class="board board-100">${Array.from({length:100},(_,i)=>{const n=i+1,s=specialCells[n],cat=triviaCategories[i%6],m=categoryMeta[cat];return `<div class="space ${s?'special '+s.type:''}" style="--cell:${s?'#fff':m.color}" title="${s?s.label:esc(cat)}"><small>${n}</small><b>${s?s.icon:m.icon}</b>${s?`<em>${s.label}</em>`:''}${state.teams.filter(t=>t.position===n).map(t=>`<span class="pawn" style="--pawn:${t.color}" title="${esc(t.name)}">${t.id==='sol'?'☀️':t.id==='luna'?'🚀':'⭐'}</span>`).join('')}</div>`}).join('')}</div>`}

function triviaQuestion(){const pr=state.prompt||{},meta=categoryMeta[state.roundCategory]||{},mainCanAnswer=state.status==='playing'&&!state.battle;return `<span class="category" style="color:${meta.color}">${meta.icon||'❓'} ${esc(state.roundCategory||pr.category)}</span><div class="question">${esc(pr.question||'Preparando pregunta…')}</div><div class="answers">${(pr.options||[]).map((a,i)=>mainCanAnswer?`<button class="answer" data-answer="${i}">${String.fromCharCode(65+i)} · ${esc(a)}</button>`:`<div class="answer">${String.fromCharCode(65+i)} · ${esc(a)}</div>`).join('')}</div>${state.battle?'<p class="answer-note">⚔️ En el duelo responden los representantes desde sus celulares.</p>':'<p class="answer-note">Podés responder aquí o desde el celular asignado.</p>'}`}

function battleSetup(){const b=state.battle,teams=(b?.teams||[]).map(team);return `<div class="battle-card"><div class="battle-icon">⚔️</div><span class="eyebrow">DUELO POR UNA ESTRELLA</span><h2>${teams.map(t=>esc(t?.name)).join(' vs. ')}</h2><p>Ambos equipos cayeron en la misma casilla. Cada uno elige a su representante para responder una pregunta de <b>${esc(b?.category)}</b>.</p><form id="battle-form"><div class="setup-grid">${teams.map(t=>`<div class="field"><label>${esc(t?.name)}</label><select class="input" name="player" required><option value="">Elegir participante…</option>${state.players.filter(p=>p.teamId===t?.id).map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div>`).join('')}</div><button class="btn primary" ${teams.some(t=>!state.players.some(p=>p.teamId===t?.id))?'disabled':''}>⚡ Iniciar duelo</button></form></div>`}

function whoSaidHost(){
  const total=state.whoSaidPlayers?.length||0,selected=Object.keys(state.whoSaidSelected||{}).length,order=state.whoSaidOrder||[],voters=Object.values(state.whoSaidGuesses||{}).filter(guesses=>Object.keys(guesses).length===Math.max(0,order.length-1)).length;
  if(state.status==='game_complete'){const points=state.whoSaidTeamPoints||{};return `<div class="result-stage winner-stage"><div class="waiting">${state.winnerTeam?'🏆🤭':'🤝🤭'}</div><span class="eyebrow">PARTIDA COMPLETA</span><h2>${state.winnerTeam?`¡Ganó ${esc(state.winnerTeam.name)}!`:'¡Terminó en empate!'}</h2><p>${state.teams.map(t=>`${esc(t.name)}: <b>${points[t.id]||0}</b> aciertos`).join(' · ')}</p><button class="btn primary" data-lobby>Volver al inicio</button></div>`}
  if(state.status==='who_said_choose')return `<div class="countdown-stage"><small>TIEMPO PARA ELEGIR</small><strong id="timer">60</strong><h2>Cada celular tiene dos frases</h2><p><b>${selected} de ${total}</b> participantes ya eligieron. Las frases aparecerán cuando termine el reloj.</p></div>`;
  if(state.status==='who_said_guess')return `<div><span class="eyebrow">VOTACIÓN SIMULTÁNEA</span><h2>¿Quién eligió cada frase?</h2><div class="who-said-host-list">${order.map((item,index)=>`<div><b>${index+1}</b><span>“${esc(item.prompt)}”</span></div>`).join('')}</div><p>En cada celular aparecen los nombres de los demás participantes para asignarles uno de estos números. Nadie vota por su propia frase.</p><div class="waiting">🕵️ ${voters} de ${total} completaron todo</div></div>`;
  if(state.status==='who_said_reveal')return `<div><span class="eyebrow">RONDA ${state.whoSaidCurrentRound||1} DE ${state.game.rounds||1} · ¡MISTERIO RESUELTO!</span><h2>Estas fueron las elecciones</h2>${order.map((item,index)=>`<div class="statline"><span><b>#${index+1}</b> “${esc(item.prompt)}”</span><b>${esc(player(item.playerId)?.name)}</b></div>`).join('')}<button class="btn primary" data-next>${(state.whoSaidCurrentRound||1)<(state.game.rounds||1)?'Siguiente ronda →':'Ver equipo ganador →'}</button></div>`
  return `<div class="result-stage"><div class="waiting">📱</div><h2>Se necesitan al menos dos participantes conectados</h2><p>Conectá un celular por participante y volvé a iniciar el juego.</p><button class="btn ghost" data-lobby>Volver</button></div>`;
}

function whoAmIHost(){
  const points=state.whoAmIPoints||{},actor=player(state.activePlayer),guessed=(state.whoAmIGuessed||[]).includes(state.activePlayer),best=Math.max(0,...Object.values(points)),turn=(state.whoAmIIndex||0)+1,total=(state.whoAmIOrder||[]).length,round=state.whoAmICurrentRound||1;
  if(state.status==='game_complete')return `<div class="result-stage winner-stage"><div class="waiting">${state.winnerTeam?'🏆🎭':best?'🤝🎭':'🎭'}</div><span class="eyebrow">${state.whoAmIMaxRounds||state.game.rounds||1} RONDAS COMPLETAS</span><h2>${state.winnerTeam?`¡Ganó ${esc(state.winnerTeam.name)}!`:best?'¡Terminó en empate!':'No hubo ganador'}</h2><p>${best?'Resultados finales':'Nadie adivinó personajes, por lo tanto ningún equipo recibe premio.'}</p><p>${state.teams.map(t=>`${esc(t.name)}: <b>${points[t.id]||0}</b> aciertos`).join(' · ')}</p><button class="btn primary" data-lobby>Volver al inicio</button></div>`;
  if(state.status==='countdown')return `<div class="countdown-stage"><small>RONDA ${round} DE ${state.whoAmIMaxRounds||state.game.rounds||1} · TURNO ${turn} DE ${total}</small><strong id="timer">10</strong><h2>${esc(actor?.name)}: teléfono a la frente</h2><p>El personaje está oculto y aparecerá automáticamente al terminar la cuenta.</p></div>`;
  const actorRow=`<button class="answer ${guessed?'selected':''}" data-who-am-i-guessed="${esc(actor?.id)}" ${state.status==='result'?'disabled':''}><span>${guessed?'✅':'⬜'} ${esc(actor?.name)}</span><small>${esc(team(actor?.teamId)?.name)}</small></button>`;
  if(state.status==='result')return `<div class="result-stage"><div class="waiting">${guessed?'🎉🎭':'🎭⏰'}</div><span class="eyebrow">RONDA ${round} DE ${state.whoAmIMaxRounds||state.game.rounds||1} · TURNO ${turn} DE ${total}</span><h2>${guessed?`¡${esc(actor?.name)} adivinó!`:'Terminó el tiempo'}</h2><div class="answers">${actorRow}</div><button class="btn primary" data-next>Siguiente participante →</button></div>`;
  return `<div><span class="eyebrow">RONDA ${round} DE ${state.whoAmIMaxRounds||state.game.rounds||1} · TURNO ${turn} DE ${total}</span><h2>${esc(actor?.name)} hace las preguntas</h2><p>Dispone de 120 segundos. Marcá el acierto apenas descubra el personaje.</p><div class="answers">${actorRow}</div><div class="panel" style="margin-top:18px"><b>Preguntas permitidas:</b> “¿Soy real?”, “¿Soy mujer?”, “¿Aparezco en películas?”, “¿Tengo poderes?”, “¿Soy deportista?”<br><small>No vale pedir el nombre, letras, iniciales ni partes de la palabra.</small></div><button class="btn ghost danger" data-time-up>Terminar turno ahora</button></div>`;
}

function threeTruthsHost(){
  const prompt=state.prompt||{},answers=state.truthAnswers||{},outcome=state.truthOutcome||{},result=state.status==='result';
  if(state.status==='game_complete')return `<div class="result-stage"><div class="waiting">🧐</div><h2>No hay más tarjetas disponibles</h2><button class="btn primary" data-lobby>Volver al inicio</button></div>`;
  const statements=(prompt.statements||[]).map((item,index)=>`<div class="answer ${result&&index===prompt.correct?'selected':''}"><b>${String.fromCharCode(65+index)}</b> · ${esc(item.text)} ${result&&index===prompt.correct?' ← MENTIRA':''}</div>`).join('');
  if(result){const teamRows=state.teams.map(t=>{const choice=answers[t.id],earned=outcome.points?.[t.id]||0,ok=choice===prompt.correct;return `<div class="statline"><span>${ok?'✅':'😜'} ${esc(t.name)} eligió ${choice===undefined?'—':String.fromCharCode(65+choice)}</span><b>+${earned}</b></div>`}).join('');return `<div><span class="eyebrow">RESULTADO DE LA RONDA</span><h2>${esc(prompt.prompt)}</h2><div class="answers">${statements}</div>${teamRows}<button class="btn primary" data-next>Siguiente personaje →</button></div>`}
  const reps=Object.entries(state.truthRepresentatives||{}).map(([teamId,playerId])=>`<span><b>${esc(team(teamId)?.name)}:</b> ${esc(player(playerId)?.name)} ${answers[teamId]!==undefined?'🔒':'📱'}</span>`).join(' · ');
  return `<div><span class="eyebrow">${esc(prompt.category)} · NIVEL ${esc(prompt.difficulty)}</span><h2>${esc(prompt.prompt)}</h2><p>${reps}</p><div class="answers">${statements}</div><p>Los representantes responden desde sus celulares. Una vez elegida, no pueden cambiar.</p></div>`;
}

function justSingHost(){const phase=state.singPhase,phaseNames={title:'1 · TÍTULO',artist:'2 · INTÉRPRETE',era:'3 · ÉPOCA'},wins=state.singPhaseWins||{},finalist=team(state.singFinalistTeam);
  if(state.status==='sing_needs_players')return `<div class="result-stage"><div class="waiting">📱🎤</div><h2>Conectá al menos un celular</h2><p>Las respuestas se eligen desde los teléfonos.</p><button class="btn ghost" data-lobby>Volver</button></div>`;
  if(state.status==='sing_question')return `<div class="sing-stage"><div class="sing-note">♫</div><span class="eyebrow">${phaseNames[phase]}</span><h2>Descubrí la canción</h2><small class="sing-clue-label">FRAGMENTO DE LA LETRA</small><div class="sing-clue">${esc(state.prompt?.excerpt||'')}</div><p>Las cuatro opciones están únicamente en los celulares. Gana esta etapa el primero que acierta.</p><div class="sing-progress">${state.teams.map(t=>`<span><i style="background:${t.color}"></i>${esc(t.name)} · ${wins[t.id]||0} aciertos</span>`).join('')}</div></div>`;
  if(state.status==='sing_content_unavailable')return `<div class="empty"><div class="big-icon">📡</div><h2>No pude cargar una letra</h2><p>Just Sing necesita conexión la primera vez que aparece cada canción. Revisá Internet y volvé a comenzar la partida.</p></div>`;
  if(state.status==='sing_perform')return `<div class="sing-stage perform"><div class="sing-note">🎤</div><span class="eyebrow">DESAFÍO FINAL</span><h2>¡A cantar, ${esc(finalist?.name)}!</h2><div class="sing-song"><strong>${esc(state.prompt?.title)}</strong><span>${esc(state.prompt?.artist)} · ${esc(state.prompt?.year)}</span></div><p>Si cantan una parte reconocible, obtienen 3 puntos. Si no pueden, conservan 1 punto.</p><div class="host-actions row"><button class="btn primary" data-resolve-sing="1">🎶 ¡La cantaron! · 3 puntos</button><button class="btn ghost" data-resolve-sing="0">😅 No pudieron · 1 punto</button></div></div>`;
  if(state.status==='sing_round_result')return `<div class="result-stage"><div class="waiting">🎤✨</div><span class="eyebrow">RONDA ${state.round} DE ${state.game.rounds||1}</span><h2>${state.singAward?`¡Se sumaron ${state.singAward} puntos!`:'Esta vez nadie sumó'}</h2><button class="btn primary" data-next>Siguiente canción →</button></div>`;
  if(state.status==='game_complete')return `<div class="result-stage winner-stage"><div class="waiting">${state.winnerTeam?'🏆🎤':'🎵'}</div><span class="eyebrow">JUST SING · ${state.game.rounds||1} RONDAS</span><h2>${state.winnerTeam?`¡Ganó ${esc(state.winnerTeam.name)}!`:'Terminó sin ganador'}</h2><p>${state.teams.map(t=>`${esc(t.name)}: <b>${state.singMatchPoints?.[t.id]||0}</b> puntos`).join(' · ')}</p><button class="btn primary" data-lobby>Volver al inicio</button></div>`;
  return `<div class="result-stage"><div class="waiting">🎤</div><h2>Preparando la canción…</h2></div>`}

function incognitoHost(){const clues=state.prompt?.clues||[],buzz=player(state.mysteryBuzzPlayer),winner=state.mysteryRoundWinner;
  if(state.status==='game_complete')return `<div class="result-stage winner-stage"><div class="waiting">🏆🕵️</div><span class="eyebrow">PARTIDA COMPLETA</span><h2>${state.winnerTeam?`¡Ganó ${esc(state.winnerTeam.name)}!`:'¡Terminó en empate!'}</h2><button class="btn primary" data-lobby>Volver al inicio</button></div>`;
  if(state.status==='mystery_result')return `<div class="mystery-stage revealed"><span class="eyebrow">PERSONAJE REVELADO</span><div class="mystery-name">${esc(state.prompt?.answer||'')}</div><h2>${winner?`🎉 ¡${esc(winner.player)} acertó!`:'Nadie logró descubrirlo'}</h2><p>${winner?`Su equipo suma ${winner.points} punto${winner.points===1?'':'s'}.`:'Los equipos no suman puntos en esta ronda.'}</p><button class="btn primary" data-next>${state.round<(state.game.rounds||1)?'Siguiente personaje →':'Ver resultado final →'}</button></div>`;
  return `<div class="mystery-stage"><span class="eyebrow">PISTA ${Math.min(20,(state.mysteryClueIndex||0)+1)} DE 20 · RONDA ${state.round} DE ${state.game.rounds||1}</span>${buzz?`<div class="mystery-buzzed">🔴 ${esc(buzz.name)} está arriesgando…</div>`:`<p>Una nueva pista aparece cada 6 segundos</p>`}<div class="mystery-clues">${clues.map((clue,index)=>`<div><b>${index+1}</b><span>${esc(clue)}</span></div>`).join('')}</div></div>`}
function bombHost(){const holder=player(state.bombHolder),hints=state.prompt?.hints||[],wins=state.bombRoundWins||{};
  if(state.status==='game_complete')return `<div class="result-stage winner-stage"><div class="waiting">🏆💣</div><h2>${state.winnerTeam?`¡Ganó ${esc(state.winnerTeam.name)}!`:'¡Empate!'}</h2><p>${state.teams.map(t=>`${esc(t.name)}: ${wins[t.id]||0} rondas`).join(' · ')}</p><button class="btn primary" data-lobby>Volver al inicio</button></div>`;
  if(state.status==='bomb_result')return `<div class="result-stage"><div class="waiting">💥</div><span class="eyebrow">RONDA ${state.round} DE 3</span><h2>¡Ganó ${esc(state.bombRoundWinner?.name||'el rival')}!</h2><p>${esc(state.bombRoundWinner?.reason||'')}</p><div class="mystery-answer">${esc(state.prompt?.answer||'')}</div><button class="btn primary" data-next>${state.round<3?'Siguiente ronda →':'Ver resultado final →'}</button></div>`;
  return `<div class="bomb-stage"><span class="eyebrow">RONDA ${state.round} DE 3</span><h2>${esc(state.prompt?.question||'')}</h2><div class="bomb-device"><b>💣</b><span id="timer">15</span><small>segundos</small></div><h3>La alerta está con ${esc(holder?.name||'—')} · ${esc(team(holder?.teamId)?.name||'')}</h3>${state.status==='bomb_guess'?`<div class="mystery-buzzed">✍️ Está arriesgando · reloj congelado</div>`:''}<div class="mystery-clues">${hints.map((hint,i)=>`<div><b>${i+1}</b><span>${esc(hint)}</span></div>`).join('')}</div><p>${state.teams.map(t=>`${esc(t.name)}: <b>${wins[t.id]||0}</b> rondas`).join(' · ')}</p></div>`}

function playView(){const g=games[state.game.id],t=team(state.activeTeam),p=player(state.activePlayer),prompt=state.prompt||{},result=state.status==='result',counting=state.status==='countdown';let roundBody='';
  if(state.game.id==='bomba')roundBody=bombHost();
  else if(state.game.id==='incognito')roundBody=incognitoHost();
  else if(state.game.id==='just_sing')roundBody=justSingHost();
  else if(state.game.id==='tres_verdades')roundBody=threeTruthsHost();
  else if(state.game.id==='quien_soy')roundBody=whoAmIHost();
  else if(state.game.id==='quien_dijo')roundBody=whoSaidHost();
  else if(state.status==='game_complete'&&state.game.id==='mimica')roundBody=`<div class="result-stage"><div class="waiting">🎭🏆</div><span class="eyebrow">PARTIDA COMPLETA</span><h2>¡Todos hicieron su mímica!</h2><p>Cada participante actuó una vez cada uno en las ${state.game.rounds||1} ronda${(state.game.rounds||1)===1?'':'s'}.</p><button class="btn primary" data-lobby>Volver al inicio</button></div>`;
  else if(state.game.id==='trivia'){
    if(state.status==='await_roll'){const connected=state.players.filter(x=>x.teamId===t?.id&&x.online);roundBody=`<div class="dice-stage"><span class="eyebrow">TURNO DE ${esc(t?.name)}</span><h2>¡Tirá los dados!</h2><p>${connected.length?'El sistema elegirá de forma rotativa quién recibe la pregunta en su celular.':'Para tirar los dados, al menos un participante del equipo debe conectarse con su celular.'}</p>${state.lastRoll?`<div class="dice-pair">${state.lastRoll.dice.map(d=>`<span>${d}</span>`).join('')}</div>`:''}<button class="btn primary big-action" data-roll ${connected.length?'':'disabled'}>🎲 Tirar dos dados</button><small>${connected.length} participante${connected.length===1?'':'s'} conectado${connected.length===1?'':'s'}</small></div>`}
    else if(state.status==='choose_category')roundBody=`<div><span class="eyebrow">🌈 CASILLA COMODÍN</span><h2>Elijan una categoría</h2><div class="category-picker">${triviaCategories.map(c=>`<button data-category="${esc(c)}" style="--cat:${categoryMeta[c].color}">${categoryMeta[c].icon}<b>${esc(c)}</b><small>${t?.stars?.[c]?'Ya tienen estrella':'Les falta esta estrella'}</small></button>`).join('')}</div></div>`;
    else if(state.status==='battle_setup')roundBody=battleSetup();
    else if(counting)roundBody=`<div class="countdown-stage"><small>${state.battle?'DUELO EN…':'PREGUNTA EN…'}</small><strong id="timer">3</strong><h2>${esc(state.roundCategory)}</h2><p>${state.battle?'Los representantes se preparan':`La recibe ${esc(p?.name||'el participante elegido')}`}</p></div>`;
    else if(result)roundBody=state.winnerTeam?`<div class="result-stage winner-stage"><div class="waiting">🏆🎉</div><span class="eyebrow">¡TENEMOS GANADOR!</span><h2>¡Ganó ${esc(state.winnerTeam.name)}!</h2><p>Llegó a la casilla 100 y consiguió las seis estrellas.</p><button class="btn primary" data-lobby>Celebrar y volver al inicio</button></div>`:`<div class="result-stage ${state.lastAnswerCorrect?'answer-correct':'answer-wrong'}"><div class="waiting">${state.lastAnswerCorrect?'🎉':'😜'}</div><h2>${state.lastAnswerCorrect?'¡Respuesta correcta!':'¡Respuesta incorrecta!'}</h2><p>La respuesta correcta era <b>${esc(prompt.options?.[prompt.correct])}</b>.</p><button class="btn primary" data-next>Siguiente turno →</button></div>`;
    else roundBody=`<div><p>Responde <b style="color:${t?.color}">${state.battle?'el representante más rápido':esc(t?.name)}</b></p>${triviaQuestion()}</div>`;
  }else{
    const secretLine=state.game.id==='rapido'?esc(prompt.prompt):`La consigna secreta está en el celular de ${esc(p?.name||'quien juega')}`;
    if(counting)roundBody=`<div class="countdown-stage"><small>5 SEGUNDOS PARA PENSAR</small><strong id="timer">5</strong><h2>${esc(p?.name||t?.name)}</h2><p>El reloj del turno todavía está pausado</p>${state.game.id==='mimica'&&state.revealedHint?`<div class="mimica-hint"><span>💡 PISTA PARA TODOS</span><strong>${esc(state.revealedHint)}</strong></div>`:''}</div>`;
    else if(result)roundBody=`<div class="result-stage"><div class="waiting">⏰</div><h2>${esc(state.activity[0])}</h2>${state.game.id==='mimica'?`<p>Acertaron <b>${state.turnCorrect||0}</b> consignas · Usaron ${state.passesUsed||0} pases y ${state.helpsUsed||0} pistas</p><small>Ronda ${state.mimicaCurrentRound||1} de ${state.game.rounds||1} · Participante ${(state.mimicaTurnIndex||0)+1} de ${(state.mimicaOrder||[]).length}</small>`:''}<button class="btn primary" data-next>${state.game.id==='mimica'&&(state.mimicaTurnIndex||0)+1>=(state.mimicaOrder||[]).length?((state.mimicaCurrentRound||1)<(state.game.rounds||1)?`Comenzar ronda ${(state.mimicaCurrentRound||1)+1} →`:'Ver resultado final →'):'Siguiente participante →'}</button></div>`;
    else roundBody=`<div><p>Turno de <b style="color:${t?.color}">${esc(t?.name)}</b>${p?` · actúa ${esc(p.name)}`:''}</p>${state.game.id==='mimica'?`<small>Ronda ${state.mimicaCurrentRound||1} de ${state.game.rounds||1} · Participante ${(state.mimicaTurnIndex||0)+1} de ${(state.mimicaOrder||[]).length}</small>`:''}<span class="category">${g.name} · ${esc(prompt.category||'Sorpresa')}</span><div class="question">${secretLine}</div>${state.game.id==='mimica'&&state.revealedHint?`<div class="mimica-hint"><span>💡 PISTA PARA TODOS</span><strong>${esc(state.revealedHint)}</strong></div>`:''}<p>${state.game.id==='mimica'?`Sin hablar ni hacer sonidos · <b>${state.turnCorrect||0} aciertos</b> · ${3-(state.passesUsed||0)} pases · ${3-(state.helpsUsed||0)} pistas`:state.game.id==='dibujo'?'Sin letras, números ni gestos.':'¡El equipo debe completar el reto a tiempo!'}</p><div class="host-actions row"><button class="btn primary" data-resolve="1">✓ ¡Acertaron!</button>${state.game.id==='mimica'?'<button class="btn ghost danger" data-time-up>Terminar turno</button>':'<button class="btn ghost danger" data-resolve="0">✕ No esta vez</button>'}</div></div>`;
  }
  const showTimer=!['quien_dijo'].includes(state.game.id)&&!counting&&!['await_roll','choose_category','battle_setup','result','game_complete','mystery_guess','mystery_result'].includes(state.status),rollSummary=state.game.id==='trivia'&&state.lastRoll?`<div class="roll-summary"><span>🎲 Tirada de ${esc(t?.name)}</span><div class="roll-dice">${state.lastRoll.dice.map(d=>`<b><i>${['','⚀','⚁','⚂','⚃','⚄','⚅'][d]}</i><small>${d}</small></b>`).join('')}<strong>= ${state.lastRoll.dice.reduce((a,b)=>a+b,0)}</strong></div><em>Casilla ${state.lastRoll.from} → ${state.lastRoll.to}</em></div>`:'';
  const shownRound=state.game.id==='mimica'?(state.mimicaCurrentRound||1):state.game.id==='quien_dijo'?(state.whoSaidCurrentRound||1):(state.round||1);return `<div class="stage ${state.game.id==='trivia'?'trivia-stage':''}"><div class="game-header"><div><button class="btn ghost" data-lobby>← Salir</button><span class="eyebrow" style="margin-left:12px">RONDA ${shownRound} DE ${state.game.rounds||1}</span><h2 style="margin:8px 0 0">${g.icon} ${g.name}</h2></div>${showTimer?`<div class="timer"><span id="timer">—</span><small>seg</small></div>`:''}</div>${rollSummary}<div class="game-layout"><section><div class="panel prompt-card ${counting?'counting':''}">${roundBody}</div>${state.game.id==='trivia'?`<div class="panel board-panel" style="margin-top:18px"><div class="section-title"><h3>🏁 Tablero de 100 casillas</h3><div class="board-tools"><b>${state.game.duration}s por pregunta</b><button class="board-expand" data-expand-board title="Ampliar tablero" aria-label="Ampliar tablero">⛶</button></div></div>${board()}</div>`:''}</section><aside>${scorePanel()}</aside></div></div>`}

function defaultRounds(gameId){return gameId==='trivia'?30:gameId==='quien_soy'?10:gameId==='mimica'?1:3}
function modalHtml(){if(!modal)return'';if(modal==='team')return `<div class="modal-back" data-close-modal><div class="modal" onclick="event.stopPropagation()"><h3>✨ Nuevo equipo</h3><form id="new-team"><div class="field"><label>Nombre</label><input class="input" name="name" required autofocus placeholder="Ej: Los Invencibles"></div><div class="row"><button class="btn primary">Crear equipo</button><button type="button" class="btn ghost" data-close-modal>Cancelar</button></div></form></div></div>`;
  if(modal==='board'){return `<div class="modal-back board-modal-back" data-close-modal><div class="modal board-modal" onclick="event.stopPropagation()"><div class="section-title"><div><span class="eyebrow">CARRERA DE MENTE</span><h2>🏁 Tablero general</h2></div><button class="icon-btn board-modal-close" data-close-modal aria-label="Cerrar tablero">×</button></div><div class="board-team-legend">${state.teams.map(t=>`<span><i style="background:${t.color}"></i>${esc(t.name)} · casilla ${t.position||0}</span>`).join('')}</div>${board()}</div></div>`}
  if(modal==='tv'){const url=`${location.origin}/tv?room=${encodeURIComponent(roomCode)}`,qr=`https://quickchart.io/qr?size=500&margin=1&text=${encodeURIComponent(url)}`;return `<div class="modal-back" data-close-modal><div class="modal tv-connect-modal" onclick="event.stopPropagation()"><div class="modal-symbol">📺</div><span class="eyebrow">SMART TV · INTERNET</span><h2>${t('projectTV')}</h2><p>En el navegador del Smart TV ingresá esta dirección:</p><div class="tv-url">${esc(url)}</div><img src="${qr}" alt="QR para abrir la pantalla de TV"><p class="tv-help">La pantalla se actualizará automáticamente y no tendrá controles de administrador.</p><div class="row"><a class="btn primary" href="${esc(url)}" target="_blank" rel="noopener">Abrir vista TV</a><button class="btn ghost" data-close-modal>Cerrar</button></div></div></div>`}
  if(modal==='qr'){const url=joinUrl||`${location.origin}/?join=1`,qr=`https://quickchart.io/qr?size=700&margin=1&text=${encodeURIComponent(url)}`;return `<div class="modal-back qr-modal-back" data-close-modal><div class="modal qr-modal" onclick="event.stopPropagation()"><span class="eyebrow">CONECTAR CELULARES</span><h2>Escaneá para entrar</h2><img src="${qr}" alt="Código QR ampliado para unirse"><div class="join-url">${esc(url)}</div><p>Misma red Wi‑Fi · Sala <b>${esc(state.room)}</b></p><button class="btn primary" data-close-modal>Cerrar</button></div></div>`}
  if(modal?.type==='editTeam'){const t=team(modal.teamId);return `<div class="modal-back" data-close-modal><div class="modal team-modal" onclick="event.stopPropagation()"><div class="modal-symbol">✏️</div><span class="eyebrow">EDITAR EQUIPO</span><h2>${esc(t?.name)}</h2><form id="edit-team"><input type="hidden" name="teamId" value="${esc(t?.id)}"><div class="field"><label>Nuevo nombre</label><input class="input" name="name" required autofocus maxlength="24" value="${esc(t?.name)}"></div><div class="row"><button class="btn primary">Guardar cambios</button><button type="button" class="btn ghost" data-close-modal>Cancelar</button></div></form></div></div>`}
  if(modal?.type==='deleteTeam'){const t=team(modal.teamId),members=state.players.filter(p=>p.teamId===t?.id).length;return `<div class="modal-back" data-close-modal><div class="modal team-modal warning-modal" onclick="event.stopPropagation()"><div class="modal-symbol">🗑️</div><span class="eyebrow">BORRAR EQUIPO</span><h2>¿Borrar ${esc(t?.name)}?</h2><p>${members?`Sus ${members} integrante${members===1?'':'s'} pasarán automáticamente a otro equipo.`:'Este equipo no tiene integrantes.'}</p><div class="row"><button class="btn delete-btn" data-confirm-delete-team="${esc(t?.id)}">Sí, borrar equipo</button><button class="btn ghost" data-close-modal>Cancelar</button></div></div></div>`}
  if(modal?.type==='editPlayer'){const p=player(modal.playerId);return `<div class="modal-back" data-close-modal><div class="modal team-modal player-modal" onclick="event.stopPropagation()"><div class="modal-symbol">🧑‍🤝‍🧑</div><span class="eyebrow">EDITAR PARTICIPANTE</span><h2>${esc(p?.name)}</h2><form id="edit-player"><input type="hidden" name="playerId" value="${esc(p?.id)}"><div class="field"><label>Equipo</label><select class="input" name="teamId">${state.teams.map(t=>`<option value="${t.id}" ${p?.teamId===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div><div class="row"><button class="btn primary">Guardar equipo</button><button type="button" class="btn ghost" data-close-modal>Cancelar</button></div></form></div></div>`}
  if(modal?.type==='deletePlayer'){const p=player(modal.playerId);return `<div class="modal-back" data-close-modal><div class="modal team-modal warning-modal" onclick="event.stopPropagation()"><div class="modal-symbol">👋</div><span class="eyebrow">QUITAR PARTICIPANTE</span><h2>¿Quitar a ${esc(p?.name)}?</h2><p>Se eliminará de la sala y dejará de pertenecer a su equipo. Puede volver a registrarse más adelante.</p><div class="row"><button class="btn delete-btn" data-confirm-delete-player="${esc(p?.id)}">Sí, quitar participante</button><button class="btn ghost" data-close-modal>Cancelar</button></div></div></div>`}
  if(modal?.type==='reset'){return `<div class="modal-back" data-close-modal><div class="modal team-modal warning-modal" onclick="event.stopPropagation()"><div class="modal-symbol">🔄</div><span class="eyebrow">REINICIAR PARTIDA</span><h2>¿Volver todos los puntos a cero?</h2><p>Se borrarán los puntajes, posiciones y estrellas, y finalizará la partida actual. Los equipos y participantes permanecerán en la sala.</p><div class="row"><button class="btn delete-btn" data-confirm-reset>Sí, reiniciar</button><button class="btn ghost" data-close-modal>Cancelar</button></div></div></div>`}
  const g=games[selectedGame],roundOptions=selectedGame==='trivia'?[10,20,30,40,50]:selectedGame==='mimica'?[1,2,3,4,5]:[1,3,5,10];return `<div class="modal-back"><div class="modal intro-modal"><div class="intro-cover"><img src="/images/games/${selectedGame}.webp" alt="Imagen de ${esc(g.name)}"></div><span class="eyebrow">ANTES DE JUGAR</span><h2>${g.name}</h2><p class="instructions">${g.instructions}</p><button class="btn secondary" data-narrate>${narratingGame===selectedGame?'⏹ Detener explicación':'🔊 Escuchar explicación'}</button><form id="game-setup"><div class="setup-grid"><div class="field"><label>Nivel de dificultad</label><select class="input" name="difficulty"><option value="facil" ${difficulty==='facil'?'selected':''}>Fácil</option><option value="medio" ${difficulty==='medio'?'selected':''}>Medio</option><option value="dificil" ${difficulty==='dificil'?'selected':''}>Difícil</option><option value="aleatorio" ${difficulty==='aleatorio'?'selected':''}>🎲 Mezclado</option></select></div><div class="field"><label>${selectedGame==='mimica'?'Tiempo por turno':'Tiempo para responder'}</label><select class="input" name="duration">${(selectedGame==='quien_soy'?[120]:[20,30,45,60,90,120]).map(n=>`<option value="${n}" ${duration===n?'selected':''}>${n} segundos</option>`).join('')}</select></div><div class="field"><label>Cantidad de rondas</label><select class="input" name="rounds">${roundOptions.map(n=>`<option value="${n}" ${rounds===n?'selected':''}>${n} ronda${n===1?'':'s'}</option>`).join('')}</select></div></div><div class="row"><button class="btn primary">🚀 Comenzar partida</button><button type="button" class="btn ghost" data-close-modal>Volver</button></div></form></div></div>`}

function renderTriviaMobileResult(){const me=player(playerId);if(!me)return renderJoin();const t=team(me.teamId),pr=state.prompt||{},winner=state.winnerTeam;const content=winner?`<div class="waiting">🏆🎉</div><h2>¡Ganó ${esc(winner.name)}!</h2><p>Completó las seis estrellas en la casilla 100.</p>`:`<div class="waiting">${state.lastAnswerCorrect?'🎉':'😜'}</div><h2>${state.lastAnswerCorrect?'¡Correcta!':'¡Incorrecta!'}</h2><p>La respuesta era <b>${esc(pr.options?.[pr.correct])}</b>.</p>`;app.innerHTML=`<main class="mobile"><div class="brand"><div class="logo">🎲</div><div><h1>Familia en Juego</h1><small>Sala ${state.room}</small></div></div><section class="mobile-card"><div class="player" style="margin-bottom:18px;text-align:left"><div class="avatar">${esc(me.name.slice(0,2).toUpperCase())}</div><div><b>${esc(me.name)}</b><br><small>${esc(t?.name)}</small></div><span class="online" style="margin-left:auto"></span></div>${content}</section></main>`;bind()}

function renderMobile(){const me=player(playerId);if(!me)return renderJoin();const t=team(me.teamId),isSecretActor=state.activePlayer===me.id&&(state.game?.id==='mimica'||state.game?.id==='dibujo'),battlePlayers=state.battle?.players||[],canTrivia=state.game?.id==='trivia'&&state.status==='playing'&&(battlePlayers.length?battlePlayers.includes(me.id):state.activePlayer===me.id);let content='';if(!state.game)content=`<div class="waiting">🎉</div><h2>¡Estás dentro!</h2><p>Formás parte de <b style="color:${t?.color}">${esc(t?.name)}</b>.</p><p>Esperá a que el anfitrión elija el juego.</p>`;else if(state.status==='game_complete'&&state.game.id==='mimica')content=`<div class="waiting">🎭🏆</div><h2>¡Partida completa!</h2><p>Todos participaron en las ${state.game.rounds||1} ronda${(state.game.rounds||1)===1?'':'s'}.</p>`;else if(isSecretActor&&(state.status==='countdown'||state.status==='playing')){const pr=state.prompt||{};content=`<span class="eyebrow">RONDA ${state.mimicaCurrentRound||1} DE ${state.game.rounds||1}</span><span class="eyebrow">${state.status==='countdown'?'TENÉS 5 SEGUNDOS PARA PENSAR':'¡A REPRESENTAR!'}</span><div class="secret"><small>${esc(pr.category)}</small><div class="question">${esc(pr.prompt)}</div></div><p>${state.game.id==='mimica'?'Sin hablar ni hacer sonidos.':'Dibujalo sin mostrar la pantalla y sin usar letras ni números.'}</p>${state.game.id==='mimica'?`<div class="mobile-actions"><button class="btn ghost" data-pass ${state.passesUsed>=3?'disabled':''}>⏭ Pasar · ${Math.max(0,3-(state.passesUsed||0))}</button><button class="btn secondary" data-hint ${state.helpsUsed>=3||state.revealedHint?'disabled':''}>${state.revealedHint?'💡 Pista mostrada':`💡 Pedir ayuda · ${Math.max(0,3-(state.helpsUsed||0))}`}</button></div>`:''}` }else if(state.status==='countdown')content=`<div class="waiting">⏳</div><h2>${state.activePlayer===me.id||battlePlayers.includes(me.id)?'¡La próxima pregunta es para vos!':'¡Preparados!'}</h2><p>Enseguida comienza el turno de <b>${esc(team(state.activeTeam)?.name)}</b>.</p>`;else if(canTrivia){const pr=state.prompt||{};content=`<span class="eyebrow">${battlePlayers.length?'⚔️ DUELO':'TU EQUIPO RESPONDE'}</span><h2>${esc(pr.question)}</h2><div class="team-choice">${(pr.options||[]).map((a,i)=>`<button data-answer="${i}">${esc(a)}</button>`).join('')}</div>`}else if(state.game.id==='rapido'&&state.activeTeam===me.teamId){content=`<span class="eyebrow">DESAFÍO ACTIVO</span><div class="secret"><div class="question">${esc(state.prompt?.prompt)}</div></div><p>¡Ayudá a tu equipo antes de que termine el tiempo!</p>`}else content=`<div class="waiting">${games[state.game.id].icon}</div><h2>${battlePlayers.includes(me.id)?'¡Fuiste elegido para el duelo!':state.activeTeam===me.teamId?'Otro integrante responde esta vez':'Otro equipo está jugando'}</h2><p>Mirá la pantalla principal. Tu momento llegará pronto.</p>`;
  app.innerHTML=`<main class="mobile"><div class="brand"><div class="logo">🎲</div><div><h1>Familia en Juego</h1><small>Sala ${state.room}</small></div></div><section class="mobile-card"><div class="player" style="margin-bottom:18px;text-align:left"><div class="avatar">${esc(me.name.slice(0,2).toUpperCase())}</div><div><b>${esc(me.name)}</b><br><small>${esc(t?.name)}</small></div><span class="online" style="margin-left:auto"></span></div>${content}</section></main>`;bind();}

function renderJoin(){app.innerHTML=`<main class="mobile"><div class="brand"><div class="logo">🎲</div><div><h1>Familia en Juego</h1><small>Control de jugador</small></div></div><section class="mobile-card"><span class="eyebrow">¡BIENVENIDO!</span><h2>¿Quién sos?</h2><p>Ingresá tu nombre y elegí un equipo. Este celular será tu compañero de juego.</p><form id="join-form"><div class="field" style="text-align:left"><label>Tu nombre</label><input class="input" name="name" required autocomplete="name" placeholder="Ej: Mariano" style="width:100%"></div><div class="field" style="text-align:left"><label>Tu equipo</label><select class="input" name="teamId" style="width:100%">${state.teams.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></div><button class="btn primary">Entrar a la sala ${state.room}</button><p id="join-error" class="join-error" role="alert"></p></form></section></main>`;bind()}

function bind(){
  enhanceMobileControls();
  if(selectedGame==='bomba'&&modal==='intro'){const durationSelect=document.querySelector('select[name="duration"]'),roundSelect=document.querySelector('select[name="rounds"]');if(durationSelect)durationSelect.innerHTML='<option value="15" selected>15 segundos</option>';if(roundSelect)roundSelect.innerHTML='<option value="3" selected>3 rondas</option>'}
  document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});
  document.querySelectorAll('[data-game]').forEach(card=>card.onclick=e=>{if(e.target.closest('[data-play-game]'))return;selectedGame=card.dataset.game;render()});
  document.querySelectorAll('[data-play-game]').forEach(button=>button.onclick=e=>{e.stopPropagation();selectedGame=button.dataset.playGame;rounds=defaultRounds(selectedGame);modal='intro';render();if(autoNarration.enabled)narrateGame(selectedGame)});
  document.querySelectorAll('[data-difficulty]').forEach(b=>b.onclick=()=>{difficulty=b.dataset.difficulty;render()});
  $('[data-music]')?.addEventListener('click',()=>music.toggle());
  $('[data-auto-narration]')?.addEventListener('click',()=>autoNarration.toggle());
  $('[data-narrate]')?.addEventListener('click',()=>toggleNarration(selectedGame));
  $('#game-setup')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);difficulty=f.get('difficulty');duration=Number(f.get('duration'));rounds=Number(f.get('rounds')||1);stopNarration();modal=null;view='play';music.start();post({type:'startGame',game:selectedGame,difficulty,duration,rounds})});
  $('[data-scroll]')?.addEventListener('click',()=>$('#games')?.scrollIntoView({behavior:'smooth'}));
  $('[data-tv]')?.addEventListener('click',()=>{modal='tv';render()});
  $('[data-expand-board]')?.addEventListener('click',()=>{modal='board';render()});
  $('[data-open-qr]')?.addEventListener('click',()=>{modal='qr';render()});
  $('[data-add-team]')?.addEventListener('click',()=>{modal='team';render()});
  document.querySelectorAll('[data-close-modal]').forEach(b=>b.onclick=()=>{stopNarration();modal=null;render()});
  $('#new-team')?.addEventListener('submit',e=>{e.preventDefault();post({type:'addTeam',name:new FormData(e.target).get('name')});modal=null});
  document.querySelectorAll('[data-edit-team]').forEach(b=>b.onclick=()=>{modal={type:'editTeam',teamId:b.dataset.editTeam};render()});
  document.querySelectorAll('[data-delete-team]').forEach(b=>b.onclick=()=>{if(!b.disabled){modal={type:'deleteTeam',teamId:b.dataset.deleteTeam};render()}});
  $('#edit-team')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);modal=null;post({type:'renameTeam',teamId:f.get('teamId'),name:f.get('name')})});
  $('[data-confirm-delete-team]')?.addEventListener('click',e=>{const teamId=e.currentTarget.dataset.confirmDeleteTeam;modal=null;post({type:'deleteTeam',teamId})});
  $('#add-player')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);post({type:'addPlayer',name:f.get('name'),teamId:f.get('teamId')})});
  document.querySelectorAll('[data-edit-player]').forEach(b=>b.onclick=()=>{modal={type:'editPlayer',playerId:b.dataset.editPlayer};render()});
  document.querySelectorAll('[data-delete-player]').forEach(b=>b.onclick=()=>{modal={type:'deletePlayer',playerId:b.dataset.deletePlayer};render()});
  $('#edit-player')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);modal=null;post({type:'movePlayer',playerId:f.get('playerId'),teamId:f.get('teamId')})});
  $('[data-confirm-delete-player]')?.addEventListener('click',e=>{const playerId=e.currentTarget.dataset.confirmDeletePlayer;modal=null;post({type:'removePlayer',playerId})});
  document.querySelectorAll('[data-resolve]').forEach(b=>b.onclick=()=>{const ok=b.dataset.resolve==='1';music.effect(ok);showReaction(ok);post({type:'resolve',correct:ok})});
  $('[data-roll]')?.addEventListener('click',()=>post({type:'rollDice'}));
  document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>post({type:'chooseCategory',category:b.dataset.category}));
  $('#battle-form')?.addEventListener('submit',e=>{e.preventDefault();const players=[...e.target.querySelectorAll('[name="player"]')].map(s=>s.value);post({type:'startBattle',players})});
  $('[data-pass]')?.addEventListener('click',()=>post({type:'passPrompt',playerId}));
  $('[data-hint]')?.addEventListener('click',()=>post({type:'requestHint',playerId}));
  document.querySelectorAll('[data-who-said-choice]').forEach(button=>button.onclick=()=>{const choices=state.whoSaidChoices?.[playerId]||[];post({type:'chooseWhoSaidPhrase',playerId,phrase:choices[Number(button.dataset.whoSaidChoice)]})});
  document.querySelectorAll('[data-who-said-guess]').forEach(button=>button.onclick=()=>post({type:'guessWhoSaid',playerId,guessedPlayerId:button.dataset.whoSaidGuess}));
  document.querySelectorAll('[data-who-said-select]').forEach(select=>select.onchange=()=>{if(select.value)post({type:'guessWhoSaid',playerId,phraseIndex:Number(select.dataset.whoSaidSelect),guessedPlayerId:select.value})});
  document.querySelectorAll('[data-who-said-number]').forEach(button=>button.onclick=()=>post({type:'guessWhoSaid',playerId,phraseIndex:Number(button.dataset.whoSaidNumber),guessedPlayerId:button.dataset.whoSaidPerson}));
  document.querySelectorAll('[data-who-am-i-hint]').forEach(button=>button.onclick=()=>post({type:'requestWhoAmIHint',playerId}));
  document.querySelectorAll('[data-who-am-i-guessed]').forEach(button=>button.onclick=()=>post({type:'markWhoAmIGuessed',playerId:button.dataset.whoAmIGuessed}));
  document.querySelectorAll('[data-answer-lie]').forEach(button=>button.onclick=()=>post({type:'answerLie',playerId,value:Number(button.dataset.answerLie)}));
  document.querySelectorAll('[data-answer-song]').forEach(button=>button.onclick=()=>post({type:'answerSong',playerId,value:Number(button.dataset.answerSong)}));
  document.querySelectorAll('[data-resolve-sing]').forEach(button=>button.onclick=()=>post({type:'resolveSing',sang:button.dataset.resolveSing==='1'}));
  document.querySelectorAll('[data-bomb-move]').forEach(button=>button.onclick=()=>post({type:'bombAction',playerId,move:button.dataset.bombMove}));
  $('#bomb-guess')?.addEventListener('submit',e=>{e.preventDefault();post({type:'guessBomb',playerId,guess:new FormData(e.target).get('guess')})});
  $('[data-mystery-buzz]')?.addEventListener('click',()=>post({type:'buzzMystery',playerId}));
  $('#mystery-guess')?.addEventListener('submit',e=>{e.preventDefault();post({type:'guessMystery',playerId,guess:new FormData(e.target).get('guess')})});
  document.querySelectorAll('[data-time-up]').forEach(b=>b.onclick=()=>{music.effect(false);showReaction(false,'¡TIEMPO!');post({type:'timeUp'})});
  $('[data-next]')?.addEventListener('click',()=>post({type:'next'}));
  $('[data-lobby]')?.addEventListener('click',()=>{view='home';post({type:'lobby'})});
  document.querySelectorAll('[data-action="reset"]').forEach(b=>b.onclick=()=>{modal={type:'reset'};render()});
  $('[data-confirm-reset]')?.addEventListener('click',()=>{modal=null;view='home';post({type:'reset'})});
  document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=async()=>{const result=await post({type:'answer',playerId:isMobile?playerId:state.activePlayer,value:Number(b.dataset.answer)}),ok=result.state.lastAnswerCorrect,winner=result.state.winnerTeam;if(!winner||isMobile){music.effect(ok);showReaction(ok,winner?`🏆 ¡GANÓ ${winner.name}!`:null)}});
  $('#join-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target),btn=e.target.querySelector('button'),chosenTeam=f.get('teamId');btn.disabled=true;btn.textContent='Ingresando…';try{const result=await post({type:'join',name:f.get('name'),teamId:chosenTeam});playerId=result.playerId;localStorage.setItem(playerStorageKey(),playerId);localStorage.setItem(playerTokenKey(),result.playerToken);const registered=result.state.players.find(p=>p.id===playerId);if(!registered||registered.teamId!==chosenTeam)throw new Error('No se pudo confirmar el equipo elegido');btn.textContent='✓ ¡Ya estás dentro!';setTimeout(()=>location.reload(),450)}catch(err){localStorage.removeItem(playerStorageKey());localStorage.removeItem(playerTokenKey());playerId=null;renderJoin();const error=$('#join-error');if(error)error.textContent=err?.message||'No se pudo conectar con la sala'}});
  $('#import-content')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);const btn=e.target.querySelector('button');btn.disabled=true;btn.textContent='Importando…';const res=await fetch('/api/content/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:f.get('url')})});const d=await res.json();btn.disabled=false;btn.textContent='Importar';if(d.ok){stats=d.stats;toast('Contenido actualizado');render()}else toast(d.error)});
}

function updateTimer(){const el=$('#timer');if(!el)return;const left=Math.max(0,Math.ceil(((state.timerEnds||Date.now())-Date.now())/1000));el.textContent=left;if(state.status==='mystery_clues'){if(left<=0&&!timeUpSent&&!isMobile&&!isTV){timeUpSent=true;post({type:'nextMysteryClue'})}return}if(state.status==='who_said_choose'||state.status==='sing_question'){if(left<=0&&!timeUpSent&&!isMobile&&!isTV){timeUpSent=true;post({type:'timeUp'})}return}if(state.status==='countdown'){if(left<=0&&!beginSent&&!isMobile&&!isTV){beginSent=true;post({type:'beginRound'})}return}if(left<=10)el.parentElement.style.borderColor='#ff6f61';if(left===0&&state.status==='playing'){el.parentElement.classList.add('time-up');if(!timeUpSent&&!isMobile&&!isTV){timeUpSent=true;post({type:'timeUp'})}}}
function confetti(){const colors=['#ff6f61','#ffd166','#6c4cff','#16b89a'];for(let i=0;i<45;i++){const x=document.createElement('i');x.style.left=Math.random()*100+'vw';x.style.background=colors[i%4];x.style.animationDelay=Math.random()*.5+'s';x.style.transform=`rotate(${Math.random()*180}deg)`;$('#confetti').append(x);setTimeout(()=>x.remove(),2600)}}
if ('serviceWorker' in navigator) navigator.serviceWorker.register('/service-worker.js').catch(()=>{});
init().catch(err=>{app.innerHTML=`<div class="loader"><span>🔌</span><p>No pudimos conectar con el juego.<br><small>${esc(err.message)}</small></p></div>`});

function updateBombTimer(){if(state?.status!=='bomb_active'||isMobile||isTV)return;const left=Math.max(0,(state.timerEnds||0)-Date.now());if(left<=0&&!timeUpSent){timeUpSent=true;post({type:'bombExplode'})}}
